    fn interface_method_with_param(name: &str, param_ty: JavaType) -> Member {
        Member::Method(MethodDecl {
            name: name.to_string(),
            rust_name: None,
            type_params: Vec::new(),
            type_param_bounds: Vec::new(),
            return_type: JavaType::Void,
            throws: Vec::new(),
            params: vec![Param {
                name: "value".to_string(),
                source_name: "value".to_string(),
                ty: param_ty,
                is_varargs: false,
                binding: None,
            }],
            modifiers: Vec::new(),
            body: None,
            span: Default::default(),
        })
    }

    fn zero_arg_constructor(name: &str, statements: Vec<Stmt>) -> Member {
        Member::Constructor(ConstructorDecl {
            name: name.to_string(),
            rust_name: None,
            type_params: Vec::new(),
            type_param_bounds: Vec::new(),
            params: Vec::new(),
            throws: Vec::new(),
            modifiers: Vec::new(),
            body: Some(Block { statements }),
            span: Default::default(),
        })
    }

