    #[test]
    fn source_summary_nullable_receiver_call_shape_is_optional() {
        let summary = Box::leak(Box::new(
            parse_java_source(
                r#"
class Lookup {
    Path find(String sample) {
        return sample == null ? null : new Path();
    }
}

class Path {
}
"#,
            )
            .program,
        ));
        let ctx = LowerCtx {
            source_summary_type_program: summary,
            ..lower_test_ctx()
        };
        let lookup_ty = JavaType::Named {
            name: "Lookup".to_string(),
            args: Vec::new(),
        };
        let mut env = ShapeEnv::default();
        env.insert_local_shape(
            "lookup".to_string(),
            RustSlotShape::for_storage(lookup_ty.clone()),
        );
        env.insert_field_shape(
            "lookup".to_string(),
            RustSlotShape::for_storage(crate::types::optional_java_type(lookup_ty.clone())),
        );
        env.insert_local_shape(
            "sample".to_string(),
            RustSlotShape::for_storage(JavaType::String),
        );
        let expected = Some((
            OwnershipShape::Owned,
            JavaType::Named {
                name: "Path".to_string(),
                args: Vec::new(),
            },
        ));
        for receiver in [
            Expr::Var("lookup".to_string()),
            Expr::FieldAccess(Box::new(Expr::This), "lookup".to_string()),
        ] {
            let call = Expr::Call {
                receiver: Some(Box::new(receiver)),
                name: "find".to_string(),
                args: vec![Expr::Var("sample".to_string())],
                resolved: None,
            };

            assert_eq!(
                planned_method_call_return_shape(&call, &env, ctx).and_then(|shape| {
                    shape
                        .optional_element_type()
                        .map(|element_ty| (shape.ownership, element_ty))
                }),
                expected
            );
        }

        let mut shared_field_env = ShapeEnv::default();
        let mut shared_optional_lookup =
            RustSlotShape::for_storage(crate::types::optional_java_type(lookup_ty.clone()));
        shared_optional_lookup.ownership = OwnershipShape::SharedBorrow;
        shared_field_env.insert_field_shape_with_access_name_and_java_type(
            "lookup",
            "lookup",
            shared_optional_lookup,
            lookup_ty,
        );
        shared_field_env.insert_local_shape(
            "sample".to_string(),
            RustSlotShape::for_storage(JavaType::String),
        );
        let call = Expr::Call {
            receiver: Some(Box::new(Expr::FieldAccess(
                Box::new(Expr::This),
                "lookup".to_string(),
            ))),
            name: "find".to_string(),
            args: vec![Expr::Var("sample".to_string())],
            resolved: None,
        };

        assert_eq!(
            planned_method_call_return_shape(&call, &shared_field_env, ctx).and_then(|shape| {
                shape
                    .optional_element_type()
                    .map(|element_ty| (shape.ownership, element_ty))
            }),
            expected
        );
    }

